<script setup lang="ts">
import {computed,reactive,ref,watch} from 'vue'
import {ElMessage} from 'element-plus'
import type {Row} from '../api/types'
import {post} from '../api/http'
import {useMediaQuery} from '../composables/useMediaQuery'
import {useAuth} from '../stores/auth'
import {useResource,useMutation,number,money,confirmAction} from '../composables/useResource'
import PageHeader from '../components/PageHeader.vue'
import ResourceState from '../components/ResourceState.vue'
import DataTable from '../components/DataTable.vue'
import MaterialReturnDialog from '../components/MaterialReturnDialog.vue'
const auth=useAuth(),stock=useResource<Row[]>('/inventory',[]),movements=useResource<Row[]>('/stock-movements',[]),issueRecords=useResource<Row[]>('/issues',[]),returnRecords=useResource<Row[]>('/issue-returns',[])
const selectedIssue=ref<Row>(),returnDialog=ref(false)
const tab=ref('inventory'),warehouse=ref<any>(''),lowOnly=ref(false),dialog=ref(false),result=ref<Row|null>(null)
const form=reactive<{project_id:any;warehouse_id:any;reference:string;note:string;items:{material_id:any;quantity:number}[]}>({project_id:'',warehouse_id:'',reference:'',note:'',items:[]})
const rows=computed(()=>stock.data.value.filter(r=>(!warehouse.value||String(r.warehouse_id)===String(warehouse.value))&&(!lowOnly.value||Number(r.quantity)<Number(r.safety_stock))).map(r=>({...r,id:`${r.warehouse_id}-${r.material_id}`})))
const available=computed(()=>stock.data.value.filter(r=>String(r.warehouse_id)===String(form.warehouse_id)&&Number(r.quantity)>0))
const {saving,run}=useMutation(async()=>{await Promise.all([stock.load(),movements.load(),issueRecords.load(),returnRecords.load()])})
function openIssue(){Object.assign(form,{project_id:'',warehouse_id:'',reference:'',note:'',items:[{material_id:'',quantity:1}]});result.value=null;dialog.value=true}
watch(()=>form.warehouse_id,()=>form.items=[{material_id:'',quantity:1}])
const remaining=(material:any)=>available.value.find(r=>String(r.material_id)===String(material))
async function issue(){if(!form.project_id||!form.warehouse_id||!form.reference.trim()||!form.items.length||form.items.some(i=>!i.material_id||!Number.isFinite(i.quantity)||i.quantity<=0)){ElMessage.warning('请选择项目、仓库，填写领料凭证和材料数量');return}if(new Set(form.items.map(i=>String(i.material_id))).size!==form.items.length){ElMessage.warning('同一材料不可重复');return}if(form.items.some(i=>i.quantity>Number(remaining(i.material_id)?.quantity||0))){ElMessage.warning('领料数量超出当前库存，请调整或刷新数据');return}if(!await confirmAction('确认领料出库？材料成本将计入所选项目。'))return;if(await run(async()=>{result.value=await post<Row>('/issues',form)},'领料出库成功'))dialog.value=false}
async function reload(){await Promise.all([stock.load(),movements.load(),issueRecords.load(),returnRecords.load()])}
const isMobile=useMediaQuery()
</script>
<template><PageHeader title="库存与领料" subtitle="库存按仓库管理，领料按项目归集成本，出入库全过程留痕。"><el-button :loading="stock.loading.value||movements.loading.value" @click="reload">刷新</el-button><el-button v-if="auth.can('inventory:issue')" type="primary" @click="openIssue">＋ 项目领料出库</el-button></PageHeader><el-alert v-if="result" :title="`领料已入账 · 单据 ${result.code||result.id} · 服务端成本 ¥ ${money(result.amount)}`" type="success" show-icon class="mb" @close="result=null"/><section class="panel table-panel"><el-tabs v-model="tab"><el-tab-pane label="实时库存" name="inventory"><ResourceState :error="stock.error.value" :loading="stock.loading.value" @retry="stock.load"><DataTable :rows="rows" :columns="[{key:'material_name',label:'材料名称',minWidth:170},{key:'specification',label:'规格型号',minWidth:140},{key:'warehouse_name',label:'仓库',minWidth:150},{key:'unit',label:'单位',width:70},{key:'quantity',label:'现存数量',number:true},{key:'safety_stock',label:'安全库存',number:true},{key:'average_price',label:'加权均价（元）',money:true,minWidth:150},{key:'stock_value',label:'库存金额（元）',money:true,minWidth:150}]"><template #toolbar><el-select v-model="warehouse" clearable placeholder="全部仓库" style="width:170px"><el-option v-for="w in auth.catalog.warehouses" :key="w.id" :label="w.name" :value="w.id"/></el-select><el-checkbox v-model="lowOnly">仅看低库存</el-checkbox></template><template #quantity="{row}"><el-tag v-if="Number(row.quantity)<Number(row.safety_stock)" type="danger" effect="plain">{{number(row.quantity)}} · 库存不足</el-tag><span v-else class="numeric">{{number(row.quantity)}}</span></template></DataTable></ResourceState></el-tab-pane><el-tab-pane label="出入库流水" name="movements"><ResourceState :error="movements.error.value" :loading="movements.loading.value" @retry="movements.load"><DataTable :rows="movements.data.value" :columns="[{key:'reference',label:'业务凭证',minWidth:170},{key:'kind',label:'业务类型',status:true,width:110},{key:'material_name',label:'材料名称'},{key:'warehouse_name',label:'所属仓库'},{key:'project_name',label:'归属项目',minWidth:180},{key:'quantity',label:'数量',number:true},{key:'unit_cost',label:'单位成本',money:true},{key:'amount',label:'金额',money:true},{key:'operator_name',label:'经办人'},{key:'created_at',label:'发生时间',date:true,minWidth:170}]"/></ResourceState></el-tab-pane><el-tab-pane label="领料与退料" name="issues"><ResourceState :error="issueRecords.error.value" :loading="issueRecords.loading.value" @retry="issueRecords.load"><DataTable :rows="issueRecords.data.value" :columns="[{key:'code',label:'原领料单号'},{key:'project_name',label:'领料项目'},{key:'warehouse_name',label:'出库仓库'},{key:'amount',label:'原领料成本（元）',money:true},{key:'reference',label:'领料凭证'},{key:'operator_name',label:'领料人'},{key:'created_at',label:'领料时间',date:true}]"><template v-if="auth.can('inventory:issue')" #actions="{row}"><el-button link type="primary" :disabled="!row.items?.some((i:Row)=>Number(i.returnable_quantity)>0)" @click="selectedIssue=row;returnDialog=true">办理项目退料</el-button></template></DataTable></ResourceState></el-tab-pane><el-tab-pane label="退料记录" name="returns"><ResourceState :error="returnRecords.error.value" :loading="returnRecords.loading.value" @retry="returnRecords.load"><DataTable :rows="returnRecords.data.value" :columns="[{key:'code',label:'退料单号'},{key:'issue_code',label:'原领料单'},{key:'project_name',label:'所属项目'},{key:'warehouse_name',label:'退回仓库'},{key:'amount',label:'退回原成本（元）',money:true},{key:'reference',label:'退料凭证'},{key:'reason',label:'退料原因'},{key:'operator_name',label:'经办人'},{key:'created_at',label:'退料时间',date:true}]"/></ResourceState></el-tab-pane></el-tabs></section><el-dialog v-model="dialog" title="项目多材料领料出库" width="900px" :close-on-click-modal="false"><el-form label-position="top"><div class="form-grid"><el-form-item label="领料项目 *"><el-select v-model="form.project_id" filterable><el-option v-for="p in auth.catalog.projects" :key="p.id" :label="p.name" :value="p.id"/></el-select></el-form-item><el-form-item label="出库仓库 *"><el-select v-model="form.warehouse_id" filterable><el-option v-for="w in auth.catalog.warehouses" :key="w.id" :label="w.name" :value="w.id"/></el-select></el-form-item><el-form-item label="领料凭证号 *"><el-input v-model="form.reference" placeholder="填写真实领料凭证编号"/></el-form-item><el-form-item label="领料用途"><el-input v-model="form.note"/></el-form-item></div><div class="subheading"><h3>领料明细</h3><el-button size="small" type="primary" plain :disabled="!form.warehouse_id" @click="form.items.push({material_id:'',quantity:1})">＋ 添加材料</el-button></div><div v-if="isMobile" class="mobile-form-lines"><section v-for="(row,index) in form.items" :key="index" class="mobile-form-line"><div class="subheading"><h3>领料材料 {{index+1}}</h3><el-button type="danger" plain :aria-label="`删除领料材料 ${index+1}`" @click="form.items.splice(index,1)">删除</el-button></div><el-form-item label="材料 / 规格"><el-select v-model="row.material_id" filterable :disabled="!form.warehouse_id" placeholder="先选择出库仓库"><el-option v-for="m in available" :key="m.material_id" :label="`${m.material_name} · ${m.specification||m.unit}`" :value="m.material_id"/></el-select></el-form-item><p class="field-hint">可用库存：{{number(remaining(row.material_id)?.quantity)}} {{remaining(row.material_id)?.unit}}</p><el-form-item label="领料数量"><el-input-number v-model="row.quantity" :min="0.001" :precision="3" controls-position="right" style="width:100%"/></el-form-item></section></div><el-table v-else :data="form.items" border><el-table-column label="材料 / 规格" min-width="270"><template #default="{row}"><el-select v-model="row.material_id" filterable :disabled="!form.warehouse_id" placeholder="先选择出库仓库"><el-option v-for="m in available" :key="m.material_id" :label="`${m.material_name} · ${m.specification||m.unit}`" :value="m.material_id"/></el-select></template></el-table-column><el-table-column label="可用库存" width="140"><template #default="{row}">{{number(remaining(row.material_id)?.quantity)}} {{remaining(row.material_id)?.unit}}</template></el-table-column><el-table-column label="领料数量" width="200"><template #default="{row}"><el-input-number v-model="row.quantity" :min="0.001" :precision="3" controls-position="right" style="width:100%"/></template></el-table-column><el-table-column label="操作" width="80"><template #default="{$index}"><el-button link type="danger" @click="form.items.splice($index,1)">删除</el-button></template></el-table-column></el-table><p class="field-hint">提交后由服务端校验实时库存并计算移动加权成本，费用归集到所选项目。</p></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="issue">确认出库</el-button></template></el-dialog><MaterialReturnDialog v-model="returnDialog" title="项目退料入库" :endpoint="`/issues/${selectedIssue?.id}/returns`" :items="selectedIssue?.items||[]" hint="按原领料实际成本退回原仓，冲减项目材料消耗；采购应付和付款保持不变。" @saved="reload"/></template>
